{"teams/alpha/compose.yaml": "{
  "services": {
    "alpha": {
      "image": "busybox:1.36",
      "build": {
        "context": "./src",
        "dockerfile": "Dockerfile"
      },
      "command": [
        "sh",
        "-c",
        "cat /etc/team/config; sleep 300"
      ],
      "env_file": [
        "./runtime.env"
      ],
      "environment": {
        "S06_INCLUDE_LABEL": "${S06_INCLUDE_LABEL:-fallback}"
      },
      "labels": {
        "org.opsforge.include.label": "${S06_INCLUDE_LABEL:-fallback}"
      },
      "networks": [
        "alpha_mesh"
      ],
      "volumes": [
        {
          "type": "bind",
          "source": "./config.txt",
          "target": "/etc/team/config",
          "read_only": true
        },
        {
          "type": "volume",
          "source": "alpha_data",
          "target": "/data"
        }
      ]
    }
  },
  "networks": {
    "alpha_mesh": {
      "name": "opsforge-s06-model-only-shared",
      "external": true
    }
  },
  "volumes": {
    "alpha_data": {
      "name": "opsforge-s06-model-only-alpha-data",
      "external": true
    }
  }
}
